package dinkplugin.message.templating.impl;

import dinkplugin.message.templating.Evaluable;
import lombok.Builder;
import lombok.Singular;
import lombok.Value;

import java.util.Collection;
import java.util.Iterator;

@Value
@Builder
public class JoiningReplacement implements Evaluable {
    @Singular
    Collection<Evaluable> components;
    @Builder.Default
    String delimiter = "";
    @Builder.Default
    String prefix = "";
    @Builder.Default
    String postfix = "";

    @Override
    public String evaluate(boolean rich) {
        if (components.isEmpty())
            return "";

        StringBuilder sb = new StringBuilder();
        sb.append(prefix);
        Iterator<Evaluable> it = components.iterator();
        sb.append(it.next().evaluate(rich));
        while (it.hasNext()) {
            sb.append(delimiter);
            sb.append(it.next().evaluate(rich));
        }
        sb.append(postfix);
        return sb.toString();
    }
}

package dinkplugin.message.templating;

import lombok.RequiredArgsConstructor;

import java.util.Objects;
import java.util.function.Supplier;

@RequiredArgsConstructor
public final class LazyEvaluable implements Evaluable {
    private final Supplier<Evaluable> supplier;
    private Evaluable resolved = null;

    @Override
    public String evaluate(boolean rich) {
        return this.resolve().evaluate(rich);
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Evaluable)) return false;
        Evaluable that = (Evaluable) o;
        return this.evaluate(false).equals(that.evaluate(false))
            && this.evaluate(true).equals(that.evaluate(true));
    }

    @Override
    public int hashCode() {
        return this.resolve().hashCode();
    }

    private Evaluable resolve() {
        Evaluable e = this.resolved;
        if (e != null) return e;
        return this.resolved = this.supplier.get();
    }

    public static LazyEvaluable of(Supplier<Evaluable> supplier) {
        return new LazyEvaluable(supplier);
    }
}

